// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Load Oswald font at module level to guarantee availability before render
const { fontFamily: oswaldFamily } = loadOswald();



export type StreakFlameAnimationProps = Record<string, any>;

const StreakFlameAnimation: React.FC<StreakFlameAnimationProps> = ({
  backgroundColor = "#110517",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryPurple = "#301934",
  secondaryOrange = "#DC4405",
  streakCount = 9,
  streakTextTop = "PICK",
  streakTextBottom = "STREAK",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely handle transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const centerX = width * 0.5;
  const centerY = height * 0.5;

  // Animations
  const flameScale = spring({
    fps,
    frame: frame - 5,
    config: { damping: 12, mass: 1.2 },
  });

  // Organic wave for the flame container
  const flameAngle = interpolate(
    Math.sin(frame * 0.1) + Math.cos(frame * 0.15),
    [-2, 2],
    [-5, 5]
  );

  // Counter logic
  const currentStreak = Math.floor(
    interpolate(frame, [15, 45], [0, streakCount], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const numberScale = spring({
    fps,
    frame: frame - 15,
    config: { damping: 10, mass: 1 },
  });

  const textXOffset = interpolate(
    spring({ fps, frame: frame - 25, config: { damping: 12 } }),
    [0, 1],
    [50, 0]
  );
  
  const textOpacity = interpolate(frame - 25, [0, 10], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Dynamic Flame Stops
  const purpleLimit = interpolate(Math.sin(frame * 0.1), [-1, 1], [30, 45]);
  const orangeLimit = interpolate(Math.sin(frame * 0.12), [-1, 1], [65, 80]);

  // Organic stretch and squish for the flame path
  const flameStretchY = interpolate(Math.sin(frame * 0.4), [-1, 1], [0.95, 1.05]);
  const flameStretchX = interpolate(Math.cos(frame * 0.4), [-1, 1], [0.98, 1.02]);

  // Ember Particles Array
  const embers = Array.from({ length: 40 }).map((_, i) => {
    const startDelay = i * 6;
    const lifetime = 80 + (i % 3) * 20; // Staggered lifetimes from 80 to 120 frames
    const localFrame = (frame + startDelay) % lifetime;
    
    // Spark rising motion
    const yPos = interpolate(
      localFrame,
      [0, lifetime],
      [300, -50]
    );
    
    // Horizontal drift pattern
    const xDrift = Math.sin(localFrame * 0.05 + i) * 60;
    const xBase = 100 + (i % 5 === 0 ? -30 : i % 4 === 0 ? 30 : i % 3 === 0 ? -15 : 15);
    const xPos = xBase + xDrift * (localFrame / lifetime);
    
    const opacity = interpolate(
      localFrame,
      [0, 10, lifetime - 20, lifetime],
      [0, 1, 0.8, 0]
    );
    
    const scale = interpolate(
      localFrame,
      [0, lifetime],
      [1, 0.2]
    );

    return (
      <circle
        key={i}
        cx={xPos}
        cy={yPos}
        r={4 + (i % 4)}
        fill={i % 3 === 0 ? "#FFFFFF" : i % 2 === 0 ? "#FFC107" : secondaryOrange}
        style={{
          opacity,
          transform: `scale(${scale})`,
          transformOrigin: `${xPos}px ${yPos}px`,
          mixBlendMode: "screen",
          transition: "none"
        }}
      />
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: oswaldFamily,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        gap: "80px",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Glow Effect Behind Flame */}
      <div
        style={{
          position: "absolute",
          left: centerX - 400,
          top: centerY - 300,
          width: 600,
          height: 600,
          background: `radial-gradient(circle, ${primaryPurple}88 0%, transparent 60%)`,
          filter: "blur(60px)",
          opacity: flameScale,
          transition: "none",
        }}
      />

      {/* Flame Container */}
      <div
        style={{
          transform: `scale(${flameScale}) rotate(${flameAngle}deg)`,
          transformOrigin: "bottom center",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <svg
          width="350"
          height="525"
          viewBox="0 0 200 350"
          style={{ overflow: "visible" }}
        >
          <defs>
            <linearGradient id="flameGrad" x1="0" y1="1" x2="0" y2="0">
              <stop offset="0%" stopColor={primaryPurple} />
              <stop offset={`${purpleLimit}%`} stopColor={primaryPurple} />
              <stop offset={`${orangeLimit}%`} stopColor={secondaryOrange} />
              <stop offset="100%" stopColor="#FFC107" />
            </linearGradient>
          </defs>

          {/* Flame Core Group */}
          <g
            style={{
              transform: `scale(${flameStretchX}, ${flameStretchY})`,
              transformOrigin: "100px 330px",
              transition: "none",
            }}
          >
            {/* Outer Flame Body */}
            <path 
              d="M 100 20 C 100 20 20 120 20 220 C 20 290 60 330 100 330 C 140 330 180 290 180 220 C 180 120 100 20 100 20 Z" 
              fill="url(#flameGrad)"
            />
            
            {/* Inner Flame Layer 1 */}
            <path 
              d="M 100 110 C 100 110 50 180 50 240 C 50 280 75 310 100 310 C 125 310 150 280 150 240 C 150 180 100 110 100 110 Z" 
              fill="#FFC107"
            />

            {/* Inner Flame Layer 2 */}
            <path 
              d="M 100 180 C 100 180 70 230 70 265 C 70 290 85 300 100 300 C 115 300 130 290 130 265 C 130 230 100 180 100 180 Z" 
              fill="#FFFFFF"
            />
          </g>

          {/* Embers overlaying the flame */}
          <g>{embers}</g>
        </svg>
      </div>

      {/* Typography Layout */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            fontSize: 450,
            fontWeight: 700,
            lineHeight: 0.8,
            color: secondaryOrange,
            WebkitTextStroke: `4px ${primaryPurple}`,
            transform: `scale(${numberScale})`,
            textShadow: `0px 10px 40px ${secondaryOrange}66`,
            transition: "none",
            marginRight: 40,
          }}
        >
          {currentStreak}
        </div>
        
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            transform: `translateX(${textXOffset}px)`,
            opacity: textOpacity,
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 160,
              fontWeight: 700,
              color: "#FFFFFF",
              lineHeight: 0.9,
              letterSpacing: "4px",
              transition: "none",
            }}
          >
            {streakTextTop}
          </div>
          <div
            style={{
              fontSize: 160,
              fontWeight: 700,
              color: "#FFFFFF",
              lineHeight: 0.9,
              letterSpacing: "4px",
              transition: "none",
            }}
          >
            {streakTextBottom}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default StreakFlameAnimation;